import{_ as a,o as n,c as t,ah as o}from"./chunks/framework.D4KxWb5R.js";const m=JSON.parse('{"title":"Questions fréquentes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"src/guide/faq.md"}'),i={name:"guide/faq.md"};function r(s,e,u,d,l,c){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="questions-frequentes" tabindex="-1">Questions fréquentes <a class="header-anchor" href="#questions-frequentes" aria-label="Permalink to &quot;Questions fréquentes&quot;">​</a></h1><h2 id="je-n-ai-pas-recu-mon-invitation" tabindex="-1">Je n&#39;ai pas reçu mon invitation <a class="header-anchor" href="#je-n-ai-pas-recu-mon-invitation" aria-label="Permalink to &quot;Je n&#39;ai pas reçu mon invitation&quot;">​</a></h2><p>Regardez dans vos courriers indésirables. Sinon, demandez à l&#39;administrateur de la <a href="./administration/accounts.html">renvoyer</a> : le nouvel e-mail porte un nouveau mot de passe temporaire, l&#39;ancien ne fonctionne plus.</p><h2 id="mon-mot-de-passe-temporaire-ne-fonctionne-plus" tabindex="-1">Mon mot de passe temporaire ne fonctionne plus <a class="header-anchor" href="#mon-mot-de-passe-temporaire-ne-fonctionne-plus" aria-label="Permalink to &quot;Mon mot de passe temporaire ne fonctionne plus&quot;">​</a></h2><p>Il a expiré (7 jours par défaut). Demandez à l&#39;administrateur de renvoyer l&#39;invitation.</p><h2 id="je-ne-recois-pas-le-code-de-connexion" tabindex="-1">Je ne reçois pas le code de connexion <a class="header-anchor" href="#je-ne-recois-pas-le-code-de-connexion" aria-label="Permalink to &quot;Je ne reçois pas le code de connexion&quot;">​</a></h2><p>Attendez une minute, regardez dans vos courriers indésirables, puis cliquez sur <strong>Envoyer un nouveau code</strong>. Le code est valable 15 minutes. Si les e-mails n&#39;arrivent toujours pas, contactez l&#39;administrateur.</p><h2 id="je-ne-vois-pas-un-produit" tabindex="-1">Je ne vois pas un produit <a class="header-anchor" href="#je-ne-vois-pas-un-produit" aria-label="Permalink to &quot;Je ne vois pas un produit&quot;">​</a></h2><p>Votre périmètre ne le couvre pas. Demandez à votre responsable de pôle ou à l&#39;administrateur de l&#39;ajouter à votre compte ou à votre équipe.</p><h2 id="l-intranet-fonctionne-mais-pas-le-back-office-d-un-produit" tabindex="-1">L&#39;intranet fonctionne, mais pas le back-office d&#39;un produit <a class="header-anchor" href="#l-intranet-fonctionne-mais-pas-le-back-office-d-un-produit" aria-label="Permalink to &quot;L&#39;intranet fonctionne, mais pas le back-office d&#39;un produit&quot;">​</a></h2><p>L&#39;accès au back-office d&#39;un produit s&#39;accorde à part. Demandez-le à l&#39;administrateur (voir <a href="./administration/accounts.html">Comptes</a>). Pour Auticway, voyez aussi les <a href="./auticway.html#messages-de-refus">messages de refus</a>.</p><h2 id="je-ne-peux-pas-rattacher-une-zone-a-un-produit" tabindex="-1">Je ne peux pas rattacher une zone à un produit <a class="header-anchor" href="#je-ne-peux-pas-rattacher-une-zone-a-un-produit" aria-label="Permalink to &quot;Je ne peux pas rattacher une zone à un produit&quot;">​</a></h2><p>Seules les zones qualifiées peuvent être rattachées. Qualifiez la zone dans le <a href="./administration/registry.html#zones">registre</a>, ou demandez-le au Pôle Exploitation.</p><h2 id="j-ai-perdu-mon-telephone-d-authentification" tabindex="-1">J&#39;ai perdu mon téléphone d&#39;authentification <a class="header-anchor" href="#j-ai-perdu-mon-telephone-d-authentification" aria-label="Permalink to &quot;J&#39;ai perdu mon téléphone d&#39;authentification&quot;">​</a></h2><p>Utilisez un code de récupération pour vous connecter, puis désactivez l&#39;application dans <a href="./account.html#securite">Mon compte</a>. Sans code de récupération, contactez l&#39;administrateur.</p><h2 id="je-recois-trop-d-e-mails" tabindex="-1">Je reçois trop d&#39;e-mails <a class="header-anchor" href="#je-recois-trop-d-e-mails" aria-label="Permalink to &quot;Je reçois trop d&#39;e-mails&quot;">​</a></h2><p>Choisissez, pour chaque événement, entre la notification et l&#39;e-mail dans vos <a href="./notifications.html#choisir-comment-etre-prevenu">préférences</a>.</p><h2 id="contacts" tabindex="-1">Contacts <a class="header-anchor" href="#contacts" aria-label="Permalink to &quot;Contacts&quot;">​</a></h2><p>Pour une question à laquelle ce guide ne répond pas, adressez-vous à votre responsable de pôle ou à l&#39;administrateur général de la plateforme. Leurs coordonnées sont dans les ressources partagées de l&#39;intranet.</p>',19)])])}const h=a(i,[["render",r]]);export{m as __pageData,h as default};
